import React, { useState } from "react";
import "./ScheduleTable.css";

const ScheduleTable = ({ schedule, title, showSala = true, editable = false, onEditClick }) => {

  const [showPopup, setShowPopup] = useState(false);
  const [selectedEntry, setSelectedEntry] = useState(null);
  

  const handleEditClick = (entry) => {
    setSelectedEntry(entry);
    setShowPopup(true);
  };

  const closePopup = () => {
    setShowPopup(false);
    setSelectedEntry(null);
  };

  const handleAddNew = () => {
    const newEntry = {
      zi: "Luni", // Exemplu de date implicite
      interval: "08:00 - 10:00",
      disciplina: "Nouă Disciplina",
      tip: "Curs",
      grupa: "A1",
      sala: "C101",
      profesor: "Profesor Nou",
      an: 1,
    };
  
    fetch("http://localhost:34101/sali", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(newEntry),
    })
      .then((res) => res.json())
      .then((data) => {
        setScheduleData((prevData) => [...prevData, data]); // Adaugă noua sală în tabel
        closePopup(); // Închide pop-up-ul
      })
      .catch((err) => console.error("Eroare la adăugarea unei noi săli:", err));
  };

  if (!Array.isArray(schedule)) {
    return (
      <div className="schedule-table-container">
        <h2>{title}</h2>
        <p style={{ textAlign: "center" }}>Nu există date valide pentru acest orar.</p>
      </div>
    );
  }

  return (
    <div className="schedule-table-container">
      <h2>{title}</h2>
      <table className="schedule-table">
        <thead>
          <tr>
            <th>Zi</th>
            <th>Interval</th>
            <th>Disciplina</th>
            <th>Tip</th>
            <th>Grupa Studenților</th>
            {showSala && <th>Sală</th>}
            <th>Profesor</th>
            <th>An</th>
            {editable && <th>Acțiuni</th>} {/* Afișăm coloana de editare doar dacă editable */}
          </tr>
        </thead>
        <tbody>
          {schedule.length === 0 ? (
            <tr>
              <td colSpan={showSala ? (editable ? 9 : 8) : (editable ? 8 : 7)} style={{ textAlign: "center" }}>
                Nu există date disponibile pentru afișare.
              </td>
            </tr>
          ) : (
            schedule.map((entry, index) => {
              const an = entry.an || "-";
              const profesor = entry.profesor || "-";

              return (
                <tr key={index}>
                  <td>{entry.zi}</td>
                  <td>{entry.interval}</td>
                  <td>{entry.disciplina}</td>
                  <td>{entry.tip}</td>
                  <td>{entry.grupa || "-"}</td>
                  {showSala && <td>{entry.sala}</td>}
                  <td>{profesor}</td>
                  <td>{an}</td>
                  {editable && (
  <td>
    <button
      className="edit-button"
      onClick={() => handleEditClick(entry)}
    >
      ✏️ Editare
    </button>
  </td>
)}

{showPopup && (
  <div className="popup-overlay">
    <div className="popup-content">
      <h3>Alege o acțiune</h3>
      <p>Editezi rândul: {selectedEntry ? selectedEntry.disciplina : "N/A"}</p>
      <button onClick={() => console.log("Nou")}>Nou</button>
      <button onClick={() => console.log("Modificare")}>Modificare</button>
      <button onClick={() => console.log("Delete")}>Delete</button>
      <button onClick={closePopup}>Închide</button>
    </div>
  </div>
)}

                  )}
                </tr>
              );
            })
          )}
        </tbody>
      </table>
    </div>
  );
};

export default ScheduleTable;
